def model(regime, n, seed):
    import numpy as np
    import pandas as pd
    rng = np.random.default_rng(seed)
    if "T" in regime.config:
        T = float(regime.config["T"])
    else:
        T = 1.0
    if T < 0.6:
        T = 0.6
    if T > 1.4:
        T = 1.4
    p = 0.16 + 0.35*(T - 1.0) + 0.30*max(T - 1.2, 0.0)
    if p < 0.05:
        p = 0.05
    if p > 0.65:
        p = 0.65
    a = 87.4 - 1.7*(T - 1.0) - 0.8*max(T - 1.2, 0.0)
    b = 92.25 - 0.35*(T - 1.0) - 1.6*max(T - 1.2, 0.0)
    s1 = 1.3
    s2 = 1.0 + 0.1*abs(T - 1.0)
    u = rng.random(n)
    y = rng.normal(b, s2, n)
    m = u < p
    if int(m.sum()) > 0:
        y[m] = rng.normal(a, s1, int(m.sum()))
    y = np.clip(y, 0.0, 100.0)
    return pd.DataFrame({"unit_id": np.arange(n), "y": y})
